    /**
     * Each write's result.
     */
    val writes: List<AlinkSystemWrite>,
)

/**
 * What saving the "Clock and audio links" edits did.
 */
data class AlinkSystemSaved(
    /**
     * The model's new revision.
     */
    val revision: Long,
    /**
     * The hub's warnings about the model it kept (a unit whose firmware has
     * no audio link, or no USB-direct block): one sentence each, the hub's
     * words. Empty when there are none.
     */
    val warnings: List<String>,
)

/**
 * What `EXT_ALINK_USB` reports.
 */
data class AlinkUsbConfig(
    /**
     * 0 off, 1 rate lock, 2 phase lock.
     */
    val mode: Int,
    /**
     * `off`, `rate_lock`, `phase_lock` or `unknown`.
     */
    val modeName: String,
    /**
     * A phase error beyond 2 samples re-anchors (else it is pulled in while
     * playing).
     */
    val autoReanchor: Boolean,
    /**
     * Samples from a USB sample's arrival to its output.
     */
    val d: Int,
    /**
     * Mode 2 with D below the unit's minimum now: it runs as mode 1.
     */
    val dBelowMin: Boolean,
    /**
     * Mode 2 with D above its maximum: it runs as mode 1.
     */
    val dAboveMax: Boolean,
    /**
     * Mode 2 at 44.1 kHz: it runs as mode 1.
     */
    val rateUnsupported: Boolean,
    /**
     * What mode 2 does in lock error (the fork's WP USB3b): `mute` (the
     * default, and what firmware before WP USB3b reads as) or
     * `play_unaligned`; `unknown` for another code.
     */
    val onLockError: String,
    /**
     * The state, as [`AlinkUsbStatus::state`].
     */
    val state: String,
    /**
     * Its code.
     */
    val stateCode: Int,
)

/**
 * What `EXT_ALINK_USB_STATUS` reports.
 */
data class AlinkUsbStatus(
    /**
     * `off` (mode 0, or the source is not USB), `no_sof`, `pull_in`,
     * `rate_locked`, `anchoring`, `phase_locked`, `rejected` (the host is
     * beyond 295 ppm) or `unknown`.
     */
    val state: String,
    /**
     * Its code.
     */
    val stateCode: Int,
    /**
     * 0 free, 1 anchoring, 2 locked, 3 re-anchor pending.
     */
    val phaseState: Int,
    /**
     * 0 = 44.1, 1 = 48, 2 = 96 kHz, 0xFF other.
     */
    val rateCode: Int,
    /**
     * The rate, Hz; 0 when unknown.
     */
    val rateHz: Long,
    /**
     * RP2350 hardware SOF timestamps.
     */
    val hwTimestamp: Boolean,
    /**
     * The host plays a stream to the unit.
     */
    val stream: Boolean,
    /**
     * The host follows the SOF-locked clock.
     */
    val nominalFeedback: Boolean,
    /**
     * A usable time base.
     */
    val timeBase: Boolean,
    /**
     * No SOF for over 50 ms: the time base is extrapolated.
     */
    val holdover: Boolean,
    /**
     * The VCXO started at the host rate the unit stored (WP USB3).
     */
    val seeded: Boolean,
    /**
     * Mode 2 cannot be in step (host rejected, a configuration that cannot
     * phase-lock, or a phase error pending): the unit is muted or plays
     * unaligned, as [`AlinkUsbConfig::on_lock_error`] says (WP USB3b).
     */
    val lockError: Boolean,
    /**
     * The host's SOF rate against the unit's crystal, ppm (+ = host fast).
     */
    val hostPpm: Float,
    /**
     * The soft VCXO's correction, ppm.
     */
    val vcxoPpm: Float,
    /**
     * The phase error, samples (phase-locked only).
     */
    val phaseErrorSamples: Float,
    /**
     * The USB sample index S arriving now; 0 without a time base.
     */
    val sample: Long,
    /**
     * Its bus frame (0-2047).
     */
    val busFrame: Int,
    /**
     * The smallest D phase lock takes now.
     */
    val dMin: Int,
    /**
     * The largest.
     */
    val dMax: Int,
    /**
     * The output ring's fill, samples.
     */
    val fill: Int,
    /**
     * The bus frame the current stream's content began in (2.9.3); none
     * without a stream on the timeline.
     */
    val streamStartBusFrame: Int?,
    /**
     * Frames since then.
     */
    val streamAgeFrames: Long,
    /**
     * Silence inserted minus late samples dropped since then.
     */
    val streamShift: Int,
    /**
     * Faded gaps since boot (wraps at 65536).
     */
    val gapCount: Int,
    /**
     * Anchors since boot.
     */
    val anchors: Long,
    /**
     * Re-anchors since boot.
     */
    val reanchors: Long,
    /**
     * Silence inserted for missing packets, samples since boot.
     */
    val missedSamples: Long,
    /**
     * Samples dropped because their packet came too late, since boot.
     */
    val lateSamples: Long,
)

/**
 * One cause of timeline ends with its count (`EXT_ALINK_USB_DIAG`).
 */
data class AlinkUsbEnd(
    /**
     * `sof_lost`, `long_gap`, `discontinuity`, `host_rejected`,
     * `rate_or_config`, `reanchor_phase_error`, `reanchor_output_reset`,
     * `reanchor_other`, `stop`.
     */
    val cause: String,
    /**
     * How often.
     */
    val count: Int,
)

/**
 * What `EXT_ALINK_USB_DIAG` reports: why a unit lost its timeline.
 */
data class AlinkUsbDiag(
    /**
     * The layout read: 1, or 2 since the fork's WP USB3b (with
     * [`Self::bad_sof_readings`] and [`Self::lock_errors`]).
     */
    val version: Int,
    /**
     * The latest end's cause ([`AlinkUsbEnd::cause`]); none yet.
     */
    val lastCause: String?,
    /**
     * SOF absences ridden through.
     */
    val rides: Int,
    /**
     * SOF absences of 50 ms or more.
     */
    val holdovers: Int,
    /**
     * Timeline ends by cause, in the firmware's order.
     */
    val ends: List<AlinkUsbEnd>,
    /**
     * USB suspends.
     */
    val suspends: Int,
    /**
     * USB resumes.
     */
    val resumes: Int,
    /**
     * USB bus resets.
     */
    val busResets: Int,
    /**
     * Disconnects.
     */
    val unplugs: Int,
    /**
     * The latest absence: frames counted on the bus.
     */
    val lastFrames: Long,
    /**
     * RP2350 SOF timestamps the unit repaired (layout 2; 0 in layout 1).
     */
    val badSofReadings: Int,
    /**
     * Entries into lock error (layout 2; 0 in layout 1).
     */
    val lockErrors: Int,
    /**
     * Its duration by the unit's clock, µs.
     */
    val lastUs: Long,
    /**
     * Clock minus frames at the host rate, µs.
     */
    val lastDevUs: Int,
    /**
     * The longest absence ridden through, µs.
     */
    val longestRideUs: Long,
    /**
     * The longest main-loop pass, µs.
     */
    val maxPassUs: Long,
    /**
     * The longest time without a SOF interrupt, µs.
     */
    val maxIsrQuietUs: Long,
    /**
     * The latest SOF interrupt after its SOF, µs.
     */
    val maxIsrLateUs: Long,
    /**
     * The running holdover's age, µs.
     */
    val holdoverUs: Long,
)

/**
 * What `EXT_FRAME_COUNTER` reports, with its time base.
 */
data class AlinkTimeBaseCounter(
    /**
     * The alink frame F (time base `alink`) or the USB sample S
     * (`usb_sample`); 0 with none.
     */
    val frame: Long,
    /**
     * The unit's clock at the read, µs (wraps).
     */
    val timeUs: Long,
    /**
     * Output samples played, low 32 bits.
     */
    val outputFrames: Long,
    /**
     * `alink`, `usb_sample` or `none`.
     */
    val timeBase: String,
    /**
     * Its code (0, 1, 0xFF).
     */
    val timeBaseCode: Int,
    /**
     * The bus frame of the latest SOF (time base `usb_sample` only).
     */
    val busFrame: Int,
)

/**
 * One GET the host is asked to make.
 */
data class AutoEqFetchRequest(
    /**
     * The URL, already percent-encoded.
     */
    val url: String,
    /**
     * The `Accept` header to send, if any.
     */
    val accept: String?,
    /**
     * The `User-Agent` header to send. GitHub refuses a request without one.
     */
    val userAgent: String,
)

/**
 * What the server answered, whatever the status: a 403 or a 500 is an answer.
 */
data class AutoEqFetchResponse(
    /**
     * The HTTP status, after following redirects.
     */
    val status: Int,
    /**
     * The body, as received. Pass it for an error status too.
     */
    val body: List<Int>,
    /**
     * The `Retry-After` header in seconds; `None` if absent or a date.
     */
    val retryAfterS: Long?,
    /**
     * The `X-RateLimit-Remaining` header.
     */
    val rateLimitRemaining: Long?,
    /**
     * The `X-RateLimit-Reset` header, in Unix seconds.
     */
    val rateLimitReset: Long?,
)

/**
 * What the "Update Database" dialog shows about the database in place.
 */
data class AutoEqDatabaseInfo(
    /**
     * A user database is at `db_path`, which is what decides whether "Reset to
     * Built-in" is offered. True for a damaged file too, so it can be reset.
     */
    val hasUserDatabase: Boolean,
    /**
     * Why the file could not be read; `None` if it could, or there is none.
     */
    val problem: String?,
    /**
     * The file's format version; 0 with no readable database.
     */
    val version: Int,
    /**
     * When it was generated, ISO 8601 as the file has it; empty if unknown. An
     * imported file can say anything here: show it as text if it does not parse.
     */
    val generatedAt: String,
    /**
     * Profiles it holds.
     */
    val entryCount: Long,
)

/**
 * Where a rebuild has got to, from [`AutoEqRebuild::poll`].
 */
data class AutoEqRebuildProgress(
    /**
     * 0.0 to 1.0.
     */
    val fraction: Float,
    /**
     * A line for the progress dialog; once finished, the result in words.
     */
    val status: String,
    /**
     * The rebuild is over, one way or the other; the fields below are final.
     */
    val finished: Boolean,
    /**
     * The database was written. It may still have parts missing: see
     * `failed_profiles` and `failed_listings`. On a failure the file was left
     * as it was.
     */
    val succeeded: Boolean,
    /**
     * Once finished without success, why: `cancelled`, or an
     * [`AutoEq`](DspiError::AutoEq) code; empty otherwise.
     */
    val code: String,
    /**
     * With `code` `rate_limited`: seconds until it is worth trying again, when
     * the server said.
     */
    val retryAfterS: Long?,
    /**
     * Profiles in the database written.
     */
    val entries: Long,
    /**
     * Profiles that should have come and did not. Tell the person.
     */
    val failedProfiles: Long,
    /**
     * Directory listings that failed, whose profiles were never seen. Tell the
     * person.
     */
    val failedListings: Long,
    /**
     * Folders with no usable profile, which is normal upstream.
     */
    val skippedProfiles: Long,
)

/**
 * One filter of a profile, as the AutoEQ database has it.
 */
data class AutoEqFilter(
    /**
     * The database's shape name (`PK`, `LSC`, `HSC`, `peaking`, …).
     */
    val kind: String,
    /**
     * Centre or corner frequency in Hz.
     */
    val freq: Float,
    /**
     * Quality factor.
     */
    val q: Float,
    /**
     * Gain in dB.
     */
    val gainDb: Float,
)

/**
 * A headphone profile to preview or apply: one entry of the AutoEQ
 * database. A client that holds the database as JSON passes an entry
 * through [`AutoEqProfile::from_entry_json`] (the C ABI and the web do).
 */
data class AutoEqProfile(
    /**
     * The database's id.
     */
    val id: String,
    /**
     * The name to show, used in the undo step's label and the snapshot's.
     */
    val name: String,
    /**
     * The trim the profile expects, almost always negative.
     */
    val preampDb: Float,
    /**
     * The filters, in the database's order: filter `i` goes to band `i`.
     */
    val filters: List<AutoEqFilter>,
)

/**
 * One channel of a pair as a profile leaves it.
 */
data class AutoEqChannel(
    /**
     * The wire channel (inputs first, then outputs).
     */
    val channel: Int,
    /**
     * Whether it is an output.
     */
    val isOutput: Boolean,
    /**
     * Its level after the apply: the input's preamp, or the output's gain
     * (unchanged when the level is not applied).
     */
    val levelDb: Float,
    /**
     * Its PEQ bank after the apply, every band.
     */
    val bands: List<FilterParams>,
    /**
     * Its crossover after the apply (changed only where the limits profile
     * asks for a high-pass); empty on an input.
     */
    val crossover: List<FilterParams>,
    /**
     * Its response after the apply, PEQ and crossover, in dB at each
     * [`crate::curve_freq`] point: the graph's preview curve.
     */
    val curve: List<Double>,
)

/**
 * What a profile would do to a channel pair ([`DspiCore::autoeq_preview`]).
 */
data class AutoEqPreview(
    /**
     * The profile's id.
     */
    val profileId: String,
    /**
     * The two channels, in the order given.
     */
    val channels: List<AutoEqChannel>,
    /**
     * Where the profile's preamp goes: `input_preamp`, `output_gain`, or
     * `none` when it is not written (an output pair by default).
     */
    val levelTarget: String,
    /**
     * The profile's preamp in dB: the trim it expects. With `level_target`
     * `none`, the level to lower by hand if the correction clips.
     */
    val suggestedTrimDb: Float,
    /**
     * What the limits profile held, one row each ("eq.gain[4,0] 9 → 6
     * dB"); empty with no profile or nothing past a limit.
     */
    val held: List<String>,
    /**
     * Filter shapes of the profile this build does not know, left flat.
     */
    val unsupported: List<String>,
    /**
     * Filters past the end of the bank, left out.
     */
    val dropped: Long,
    /**
     * The lines to show: what was held, dropped and left out, in words.
     */
    val notes: List<String>,
)

/**
 * What [`DspiCore::autoeq_apply`] did.
 */
data class AutoEqApply(
    /**
     * What was written: the preview, as applied.
     */
    val preview: AutoEqPreview,
    /**
     * The snapshot of the state before, as a document
     * (`meta.kind = "snapshot"`): [`DspiCore::snapshot_recall_document`]
     * puts it back; it is the A of an A/B compare
     * ([`DspiCore::ab_start_documents`]).
     */
    val snapshotDocument: String,
    /**
     * The same snapshot's id in the store, "" when no snapshot folder is
     * named (the web) or it could not be filed (then a line in `notes`
     * says why).
     */
    val snapshotId: String,
    /**
     * What to tell the person beyond the preview's notes.
     */
    val notes: List<String>,
)

/**
 * An output's strip as a clip carries it.
 */
data class ChannelClipOutput(
    /**
     * Output gain in dB.
     */
    val gainDb: Float,
    /**
     * Output delay in ms.
     */
    val delayMs: Float,
    /**
     * Whether the output is muted.
     */
    val muted: Boolean,
)

/**
 * What [`DspiCore::copy_channel`] took from a channel. A value: a client
 * keeps it as it likes, as a record or as its JSON document
 * ([`channel_clip_to_json`]).
 */
data class ChannelClip(
    /**
     * The clip format ([`CHANNEL_CLIP_VERSION`]); a paste refuses another.
     */
    val version: Long,
    /**
     * The wire channel it was copied from (inputs, then outputs).
     */
    val sourceChannel: Int,
    /**
     * The source's name on the device ("" when unnamed); a client may put
     * the name it shows here, for its "Copied ..." line.
     */
    val sourceName: String,
    /**
     * The PEQ bank, band 0 first.
     */
    val filters: List<FilterParams>,
    /**
     * The crossover bank, slot 0 first: present when copied from an
     * output, absent from an input.
     */
    val crossover: List<FilterParams>?,
    /**
     * Gain, delay and mute: present when copied from an output.
     */
    val output: ChannelClipOutput?,
)

/**
 * How [`DspiCore::paste_channel`] pastes.
 */
data class ChannelPasteOptions(
    /**
     * The destination's linked partner (a wire channel), when the client
     * has the pair linked: its PEQ bank gets the same bands.
     */
    val mirror: Int?,
)

/**
 * What `EXT_IDENTIFY` reports: the blink state and what the board is.
 */
data class IdentifyInfo(
    /**
     * Blink time left in seconds, rounded up; 0 when not blinking.
     */
    val remainingS: Int,
    /**
     * The output of the last identify tone since the device started.
     */
    val lastToneOutput: Int?,
    /**
     * `RP2040` or `RP2350` (`chip N` for a value this build does not know).
     */
    val chip: String,
    /**
     * The SDK's chip revision number.
     */
    val chipRev: Int,
    /**
     * The raw `SYSINFO.CHIP_ID` register.
     */
    val chipId: Long,
    /**
     * The board the firmware was built for (`pico`, `pico2`).
     */
    val board: String,
    /**
     * The hardware revision the firmware build was given; empty when the
     * build set none (the firmware cannot sense it).
     */
    val hwRev: String,
)

/**
 * What `EXT_RESET_INFO` reports: why the device last restarted.
 */
data class DeviceResetInfo(
    /**
     * A stable name: `power_on`, `brownout`, `run_pin`, `watchdog`,
     * `software`, `debugger`, `glitch` or `unknown`.
     */
    val reason: String,
    /**
     * The firmware's reason code (reset_info.h), for a code this build does
     * not know too.
     */
    val reasonCode: Int,
    /**
     * The reason in words.
     */
    val description: String,
    /**
     * Seconds since that restart.
     */
    val uptimeS: Long,
    /**
     * How long the run before it lasted, in seconds; `None` after a power-on
     * or a brown-out, which clear the record.
     */
    val prevUptimeS: Long?,
    /**
     * Watchdog hangs this power session not yet acted on (the core voltage
     * extension's count).
     */
    val hangCount: Int,
    /**
     * `RP2040` or `RP2350`.
     */
    val chip: String,
    /**
     * The raw reset-cause register at boot, for a support report.
     */
    val chipReset: Long,
    /**
     * The raw `WATCHDOG.REASON` at boot (bit 8: the firmware's own timeout).
     */
    val watchdogReason: Long,
)

/**
 * What a board needs, read before it enters the bootloader. The default is
 * the safe one: unknown.
 */
data class FirmwareGuardBoard(
    /**
     * The lowest core voltage this board may be left on, in mV. 1150: not at
     * risk. Above that: at risk. Anything else, 0 included: unknown.
     */
    val requiredMv: Int,
    /**
     * Where it came from.
     */
    val source: FirmwareGuardBoardSource,
)

/**
 * The result of [`firmware_guard_check`]. The default blocks.
 */
data class FirmwareGuardVerdict(
    /**
     * True only for `Clear` and `Confirmed`. Anything else must not flash.
     */
    val allowed: Boolean,
    /**
     * The decision.
     */
    val decision: FirmwareGuardDecision,
    /**
     * Why.
     */
    val reason: FirmwareGuardReason,
    /**
     * For the user, in English.
     */
    val message: String,
    /**
     * What to ask the user to type when a risk is involved, else "": the
     * phrase, or for [`FirmwareGuardReason::Overvolt`] the word. Compared
     * exactly: case and spaces count, and the one does not stand for the other.
     */
    val confirmationPhrase: String,
    /**
     * The image's stamped voltage in mV; 0 if it has none (taken as 1150).
     */
    val imageMv: Int,
    /**
     * The board record's `required_mv`, as given.
     */
    val requiredMv: Int,
)

/**
 * A guarded apply's state: [`DspiCore::apply_status`] and every guarded call.
 */
data class GuardedApply(
    /**
     * This core's number for it (1, 2, …); 0 when none was begun.
     */
    val id: Long,
    /**
     * Where it stands.
     */
    val phase: GuardPhase,
    /**
     * What was applied: the document's or snapshot's name, or the client's
     * label for a flow.
     */
    val label: String,
    /**
     * The hub guards it too (DSPi Link with `apply_guard`): a vanished
     * client is reverted by the hub.
     */
    val hub: Boolean,
    /**
     * The timeout, ms.
     */
    val timeoutMs: Long,
    /**
     * What is left of it, ms; 0 once it has ended.
     */
    val remainingMs: Long,
    /**
     * How it ended: "" while waiting, `confirmed`, `timeout`, `reverted`
     * (Revert), `failed` (the apply itself failed), `connection_lost`,
     * `taken_over` (another console took the device's lock) or
     * `hub_stopping`.
     */
    val reason: String,
    /**
     * One plain sentence for the user, "" while waiting.
     */
    val message: String,
    /**
     * What the apply changed, in the unsaved-changes list's words.
     */
    val changes: List<String>,
    /**
     * What the apply or the revert did not do, and why.
     */
    val notes: List<String>,
)

/**
 * Which copy of the limits, the installer PIN and the pinned modes the
 * Installer page edits ([`DspiCore::installer_target`]).
 */
data class InstallerTarget(
    /**
     * [`COPY_HUB`], [`COPY_CONSOLE`] or [`COPY_NONE`].
     */
    val copy: String,
    /**
     * The page may change that copy: always for this console's own (its PIN
     * prompt is [`LockState::installer_open`]'s), for the hub's only as an
     * Admin of the hub.
     */
    val editable: Boolean,
    /**
     * The open device's serial ("" with none).
     */
    val serial: String,
    /**
     * This console's role on the hub (`viewer`, `control`, `admin`): the
     * one the hub last answered [`DspiCore::hub_limits_get`] with, else the
     * session's; "" off a hub, or while the hub session is down.
     */
    val role: String,
    /**
     * The notice row that says which copy is edited: [`NOTICE_HUB_COPY`],
     * [`NOTICE_CONSOLE_COPY`], [`NOTICE_NO_LIMITS`], or `disconnected`.
     */
    val noticeKey: String,
    /**
     * Why the page is read-only, as a notice row ([`NOTICE_HUB_ROLE`],
     * [`NOTICE_NO_LIMITS`], `disconnected`); "" when it is editable.
     */
    val readOnlyKey: String,
)

/**
 * A role's pinned mode on the hub.
 */
data class HubModePin(
    /**
     * `viewer`, `control` or `admin`.
     */
    val role: String,
    /**
     * `simple`, `advanced` or `installer`; "" for the user's choice.
     */
    val mode: String,
)

/**
 * The hub's limits, PIN and pinned modes for the open device
 * ([`DspiCore::hub_limits_get`]).
 */
data class HubAdminState(
    /**
     * The device's serial.
     */
    val serial: String,
    /**
     * This console's role on the hub.
     */
    val role: String,
    /**
     * This console may change the hub's copy (it is an Admin of the hub).
     */
    val canEdit: Boolean,
    /**
     * The hub's profile as a limits document (the `.dspipreset` family,
     * `meta.kind` `limits`); "" when the hub has none for the device.
     */
    val profileDocument: String,
    /**
     * A PIN is set on the hub for the device.
     */
    val pinSet: Boolean,
    /**
     * The hub's lock is on (a PIN set and the profile's `lockedPages`
     * non-empty).
     */
    val locked: Boolean,
    /**
     * The lock does not hold for this console (unlocked, or an Admin).
     */
    val unlocked: Boolean,
    /**
     * What the hub last held the device to (its words).
     */
    val held: List<String>,
    /**
     * Wrong PINs since the last good one (counted per device on the hub).
     */
    val wrongTries: Long,
    /**
     * The hub's refusal window left, ms; 0: none.
     */
    val retryAfterMs: Long,
    /**
     * The pinned mode of every role (an Admin sees all three), or only this
     * console's role's.
     */
    val pinnedModes: List<HubModePin>,
)

/**
 * A profile set on the hub ([`DspiCore::hub_limits_set`]).
 */
data class HubLimitsSet(
    /**
     * What the hub held the device to at once (its words), as `limits.held`.
     */
    val held: List<String>,
    /**
     * The hub's state after the change.
     */
    val state: HubAdminState,
)

/**
 * A PIN set on the hub ([`DspiCore::hub_pin_set`]).
 */
data class HubPinSet(
    /**
     * The recovery code (`XXXXX-XXXXX-XXXXX-XXXXX`): unlocks the device on
     * the hub in place of the PIN. Shown this once, never kept but as a
     * hash on the hub (notice [`NOTICE_HUB_RECOVERY`]).
     */
    val recoveryCode: String,
    /**
     * The hub's state after the change.
     */
    val state: HubAdminState,
)

/**
 * One of the hub's admin events, after the core read its lock again.
 */
data class HubAdminEvent(
    /**
     * `limits.changed` (profile or PIN), `limits.held` (the hub held the
     * device to its profile) or `mode.changed` (a role's pinned mode).
     */
    val kind: String,
    /**
     * The device it concerns ("" for `mode.changed`, which is hub-wide).
     */
    val serial: String,
    /**
     * `limits.held`'s rows.
     */
    val rows: List<String>,
    /**
     * `mode.changed`'s role.
     */
    val role: String,
    /**
     * `mode.changed`'s mode ("" unpinned).
     */
    val mode: String,
    /**
     * The open device's lock after the refresh.
     */
    val lock: LockState,
)

/**
 * Which of the hub's families this console's hub has ([`DspiCore::hub_caps`]).
 */
data class HubCaps(
    /**
     * This console has a live DSPi Link session.
     */
    val onHub: Boolean,
    /**
     * `inventory.*` ([`DspiCore::hub_inventory`]).
     */
    val inventory: Boolean,
    /**
     * `device.identify` ([`DspiCore::hub_identify`] on a hub).
     */
    val identify: Boolean,
    /**
     * `health.get` ([`DspiCore::hub_health`]).
     */
    val health: Boolean,
    /**
     * `event.*` ([`DspiCore::hub_events_read`]).
     */
    val events: Boolean,
    /**
     * The hub's snapshot store (`hub_snapshots_*`).
     */
    val hubSnapshots: Boolean,
    /**
     * The parameter API and presets by name.
     */
    val paramApi: Boolean,
    /**
     * `hub.stats` ([`DspiCore::hub_stats`]).
     */
    val hubStats: Boolean,
    /**
     * `alarm.*` ([`DspiCore::hub_alarms`]).
     */
    val alarms: Boolean,
    /**
     * `outbound.*` ([`DspiCore::hub_outbound_get`]).
     */
    val outbound: Boolean,
    /**
     * `schedule.*` ([`DspiCore::hub_schedules`]).
     */
    val schedule: Boolean,
    /**
     * `mqtt.*` ([`DspiCore::hub_mqtt_get`]).
     */
    val mqtt: Boolean,
    /**
     * API keys ([`DspiCore::hub_api_keys`]).
     */
    val apiKeys: Boolean,
    /**
     * The REST mirror is on (the hub runs with `--rest`).
     */
    val rest: Boolean,
    /**
     * Every cap of the hub's `hello`, as it sent them.
     */
    val caps: List<String>,
)

/**
 * A reset as the hub saw it (`EXT_RESET_INFO`).
 */
data class HubReset(
    /**
     * `power_on`, `brownout`, `run_pin`, `watchdog`, `software`,
     * `debugger`, `glitch` or `unknown`.
     */
    val reason: String,
    /**
     * How long the run before it lasted, s; `None` when unknown.
     */
    val prevUptimeS: Long?,
    /**
     * When it happened (ISO-8601 UTC); "" where the hub gives no time.
     */
    val at: String,
)

/**
 * One device of the hub's inventory ([`DspiCore::hub_inventory`]).
 */
data class HubDevice(
    /**
     * The key.
     */
    val serial: String,
    /**
     * Its DSPi Link handle while online.
     */
    val handle: Int?,
    /**
     * Attached now.
     */
    val online: Boolean,
    /**
     * Its name when last seen.
     */
    val name: String,
    /**
     * `RP2040`, `RP2350` (`unknown platform N` for an id this build does
     * not know); "" when unknown.
     */
    val platform: String,
    /**
     * The firmware version.
     */
    val fw: String,
    /**
     * A beta build; `None` when unknown.
     */
    val fwBeta: Boolean?,
    /**
     * Output channels.
     */
    val outputs: Int,
    /**
     * The board the firmware was built for; "" when unknown.
     */
    val board: String,
    /**
     * The hardware revision; "" when unknown or unset.
     */
    val hwRev: String,
    /**
     * The chip; "" when unknown.
     */
    val chip: String,
    /**
     * The chip's revision, when known.
     */
    val chipRev: Int?,
    /**
     * Set by an Admin; "" when unset.
     */
    val location: String,
    /**
     * Set by an Admin; "" when unset.
     */
    val note: String,
    /**
     * Set by an Admin.
     */
    val tags: List<String>,
    /**
     * First seen (ISO-8601 UTC).
     */
    val firstSeen: String,
    /**
     * Last seen: now while online, else when it went offline.
     */
    val lastSeen: String,
    /**
     * Its last reset, when the hub read one.
     */
    val lastReset: HubReset?,
)

/**
 * One online device's health ([`DspiCore::hub_health`]). A field the
 * firmware does not give, or the hub has not read yet, is `None`.
 */
data class HubHealth(
    /**
     * The device.
     */
    val serial: String,
    /**
     * Its handle.
     */
    val handle: Int,
    /**
     * The newest read (ISO-8601 UTC); "" before the first.
     */
    val at: String,
    /**
     * The busier core's load, %.
     */
    val cpuPct: Int?,
    /**
     * The sticky clip latch, one bit per channel (never cleared by the hub).
     */
    val clipMask: Long?,
    /**
     * °C, to 0.01.
     */
    val tempC: Double?,
    /**
     * Uptime, s (from the reset-info read, every 60 s).
     */
    val uptimeS: Long?,
    /**
     * Watchdog hangs not yet acted on.
     */
    val hangCount: Int?,
    /**
     * No answer for 10 s while attached.
     */
    val unresponsive: Boolean,
    /**
     * Since when, while [`HubHealth::unresponsive`]; "" otherwise.
     */
    val unresponsiveSince: String,
    /**
     * The reset seen at attach or since.
     */
    val reset: HubReset?,
)

/**
 * One attached device's counts in [`HubStats`].
 */
data class HubStatsDevice(
    /**
     * Its handle.
     */
    val handle: Int,
    /**
     * Its serial.
     */
    val serial: String,
    /**
     * Commands that ran on it since it attached.
     */
    val cmds: Long,
    /**
     * Those whose transfer failed.
     */
    val errors: Long,
    /**
     * Their mean time on the transport, ms.
     */
    val avgRttMs: Double,
    /**
     * Its notifications a full session outbox dropped.
     */
    val notifyDropped: Long,
)

/**
 * The hub's statistics ([`DspiCore::hub_stats`], Admin of the hub only).
 */
data class HubStats(
    /**
     * Network sessions open now.
     */
    val sessions: Long,
    /**
     * Seconds since the hub started.
     */
    val uptimeS: Long,
    /**
     * One row per attached device.
     */
    val devices: List<HubStatsDevice>,
)

/**
 * One record of a device's history on the hub: the event log's record
 * (`EventEntry`'s fields) and who caused it by name.
 */
data class HubEventRecord(
    /**
     * Rising per device; numbering can start again (hub-api.md section 6).
     */
    val id: Long,
    /**
     * When, ms since the Unix epoch.
     */
    val timeMs: Long,
    /**
     * The record's kind (`notification`, `connected`, `recall`, `identify`,
     * `alarm`, ...; `unknown` for a kind this build does not know).
     */
    val kind: String,
    /**
     * The device's serial.
     */
    val serial: String,
    /**
     * One readable line.
     */
    val text: String,
    /**
     * Who or what caused it, as the log's `source`; "" when none.
     */
    val source: String,
    /**
     * The DSPi Link session that caused it.
     */
    val session: Long?,
    /**
     * Who caused it, by name: the client, key, schedule or rule; "" when
     * none.
     */
    val by: String,
    /**
     * A wire channel, or a preset slot.
     */
    val channel: Int?,
    /**
     * A number: °C, a counter's total, Identify's seconds.
     */
    val value: Double?,
    /**
     * The firmware version, on connects and firmware changes.
     */
    val fw: String?,
    /**
     * The device's uptime, s.
     */
    val uptimeS: Long?,
    /**
     * Detail lines: what a recall or an import changed.
     */
    val lines: List<String>,
    /**
     * Occurrences this record stands for.
     */
    val count: Long,
)

/**
 * A page of a device's history on the hub ([`DspiCore::hub_events_read`]).
 */
data class HubEventPage(
    /**
     * The device.
     */
    val serial: String,
    /**
     * Oldest first.
     */
    val records: List<HubEventRecord>,
    /**
     * More follow the last record's id.
     */
    val more: Boolean,
    /**
     * The highest id the hub's log holds (0: empty). An `after_id` above
     * it means the numbering started again: read from 0.
     */
    val newestId: Long,
)

/**
 * One of the hub's events of these families ([`HubServerListener`]).
 */
data class HubServerEvent(
    /**
     * `event.added`, `inventory.changed` or `snapshot.changed`; P2CC2:
     * `alarm.changed`, `schedule.ran`.
     */
    val kind: String,
    /**
     * The device it concerns.
     */
    val serial: String,
    /**
     * `event.added`'s record.
     */
    val record: HubEventRecord?,
    /**
     * `inventory.changed`'s record; `None` when the device was forgotten.
     */
    val device: HubDevice?,
    /**
     * `snapshot.changed`'s snapshot id.
     */
    val snapshot: String,
    /**
     * `snapshot.changed`'s change: `put`, `rename`, `note`, `delete`.
     */
    val change: String,
    /**
     * `alarm.changed`'s alarm (raised, raised again, acknowledged or
     * cleared).
     */
    val alarm: HubAlarm?,
    /**
     * `schedule.ran`'s run.
     */
    val run: HubScheduleRun?,
)

/**
 * A snapshot on the hub with its document ([`DspiCore::hub_snapshots_get`]).
 */
data class HubSnapshotDocument(
    /**
     * Its entry.
     */
    val snapshot: SnapshotInfo,
    /**
     * The document's text (compact JSON).
     */
    val document: String,
)

/**
 * A snapshot filed on the hub ([`DspiCore::hub_snapshots_put`]).
 */
data class HubSnapshotPut(
    /**
     * Its entry on the hub.
     */
    val snapshot: SnapshotInfo,
    /**
     * False: the hub already held this snapshot with the same content.
     */
    val created: Boolean,
)

/**
 * What a recall on the hub did ([`DspiCore::hub_snapshots_recall`]).
 */
data class HubSnapshotRecall(
    /**
     * The device.
     */
    val serial: String,
    /**
     * The snapshot's id.
     */
    val snapshot: String,
    /**
     * Its name.
     */
    val name: String,
    /**
     * Whether the image was written.
     */
    val image: Boolean,
    /**
     * What changed.
     */
    val lines: List<String>,
    /**
     * What was not written, and why.
     */
    val notes: List<String>,
    /**
     * The guarded apply's id with `guard`; "" without one. Confirm it as
     * any guarded apply, or it reverts.
     */
    val guard: String,
)

/**
 * One row of the merged snapshot list ([`DspiCore::snapshot_list_merged`]).
 */
data class MergedSnapshot(
    /**
     * The entry: the hub's where it holds the id (the hub's wins).
     */
    val snapshot: SnapshotInfo,
    /**
     * [`WHERE_LOCAL`], [`WHERE_HUB`] or [`WHERE_BOTH`] (`where` in JSON).
     */
    val location: String,
    /**
     * This console's own copy of an id the hub holds with different content:
     * listed beside the hub's, never overwritten by it.
     */
    val localCopy: Boolean,
)

/**
 * The snapshots of both sides ([`DspiCore::snapshot_list_merged`]).
 */
data class SnapshotMergedList(
    /**
     * Oldest first; on an id both sides hold with different content the
     * hub's row comes first, then the local copy.
     */
    val entries: List<MergedSnapshot>,
    /**
     * The hub's list is in it (a hub with `hub_snapshots` answered).
     */
    val hubListed: Boolean,
    /**
     * Why the hub's list is not in it, as a notice row; "" when it is, or
     * when there is no such hub.
     */
    val hubNoticeKey: String,
)

/**
 * One alarm of the hub's (`alarm.list`, `alarm.ack`, `alarm.changed`).
 */
data class HubAlarm(
    /**
     * `device:<n>` or `alink:<n>`, unique for the hub's run.
     */
    val id: String,
    /**
     * `device` or `alink`.
     */
    val source: String,
    /**
     * One of [`ALARM_CODES`] (or a code a newer hub adds).
     */
    val code: String,
    /**
     * What it is about: the serial, a schedule rule's id, `hub`, or an
     * audio link unit.
     */
    val subject: String,
    /**
     * The device's serial; "" for an alarm about no one device.
     */
    val serial: String,
    /**
     * `warning` or `critical`.
     */
    val severity: String,
    /**
     * The hub's line for a person (also the notice's detail).
     */
    val message: String,
    /**
     * `raised`, `acknowledged` or `cleared`.
     */
    val state: String,
    /**
     * When it was raised (ISO-8601 UTC).
     */
    val raisedAt: String,
    /**
     * When it was cleared; "" while on.
     */
    val clearedAt: String,
    /**
     * Who acknowledged it (a client's or principal's name); "" when none.
     */
    val acknowledgedBy: String,
    /**
     * How often it was raised again while on.
     */
    val count: Long,
    /**
     * `device_restarted`'s reset reason (`watchdog`, `glitch`, `brownout`,
     * ...), read from the hub's message; "" otherwise.
     */
    val reason: String,
    /**
     * Its notice row: `alarm.<code>`, or [`NOTICE_ALARM_UNKNOWN`].
     */
    val noticeKey: String,
)

/**
 * One code's alarm rule (`alarm.rules.get`/`set`). A field the code does not
 * have is `None`; in [`DspiCore::hub_alarm_rules_set`] a `None` keeps the
 * hub's value.
 */
data class HubAlarmRule(
    /**
     * The alarm code.
     */
    val code: String,
    /**
     * The rule is on (off clears its alarms).
     */
    val on: Boolean,
    /**
     * `device_offline`, `unresponsive`: seconds (1 to 86 400).
     */
    val afterS: Long?,
    /**
     * `clip`: clip events within a minute (1 to 1000).
     */
    val perMinute: Long?,
    /**
     * `clip`: mute the device once per storm (off by default).
     */
    val muteOnStorm: Boolean?,
    /**
     * `temperature`: °C (0 to 150).
     */
    val aboveC: Double?,
    /**
     * `cpu`: % (1 to 100).
     */
    val abovePct: Long?,
    /**
     * `cpu`: for so many seconds (1 to 3600).
     */
    val forS: Long?,
)

/**
 * One action of a schedule rule. Which fields count depends on `t`:
 * `preset.load` (`slot` or `name`), `snapshot.recall` (`snapshot` or
 * `name`), `system.scene.apply` (`scene`), `param.set` (`path`, `idx`, and
 * `value` for a number or `flag` for `vol.mute`/`out.mute`).
 */
data class HubScheduleAction(
    /**
     * The message: `preset.load`, `snapshot.recall`, `system.scene.apply`
     * or `param.set`.
     */
    val t: String,
    /**
     * `preset.load`'s slot (0 to 9).
     */
    val slot: Int?,
    /**
     * A preset's or a snapshot's name ("" for none).
     */
    val name: String,
    /**
     * `snapshot.recall`'s snapshot id.
     */
    val snapshot: String,
    /**
     * `system.scene.apply`'s scene.
     */
    val scene: String,
    /**
     * `param.set`'s path: `vol.master`, `vol.user`, `vol.mute`, `out.mute`.
     */
    val path: String,
    /**
     * `param.set`'s indices.
     */
    val idx: List<Long>,
    /**
     * `param.set`'s value, a number (dB).
     */
    val value: Double?,
    /**
     * `param.set`'s value, true or false (a mute).
     */
    val flag: Boolean?,
)

/**
 * What a rule last did.
 */
data class HubScheduleLast(
    /**
     * When (ISO-8601 UTC).
     */
    val at: String,
    /**
     * Every action went through.
     */
    val ok: Boolean,
    /**
     * The time was skipped (a clock jump).
     */
    val skipped: Boolean,
)

/**
 * A schedule rule (`schedule.list`, `schedule.set`).
 */
data class HubScheduleRule(
    /**
     * The hub's id (`r1`, ...); "" for a new rule.
     */
    val id: String,
    /**
     * 1 to 48 characters.
     */
    val name: String,
    /**
     * On its schedule (`run_now` runs it either way).
     */
    val enabled: Boolean,
    /**
     * Weekly: `mon` to `sun` (with [`HubScheduleRule::time`]); empty for a
     * one-off.
     */
    val days: List<String>,
    /**
     * Weekly: local `HH:MM`.
     */
    val time: String,
    /**
     * One-off: a local `YYYY-MM-DDTHH:MM` ("" for a weekly rule).
     */
    val once: String,
    /**
     * 1 to 16.
     */
    val actions: List<HubScheduleAction>,
    /**
     * At most 16 serials.
     */
    val targets: List<String>,
    /**
     * The next run (ISO-8601 UTC); "" when none within a week or while the
     * clock is unset. Read only.
     */
    val nextRun: String,
    /**
     * The last run. Read only.
     */
    val last: HubScheduleLast?,
)

/**
 * The hub's schedule (`schedule.list`).
 */
data class HubSchedules(
    /**
     * The rules.
     */
    val rules: List<HubScheduleRule>,
    /**
     * The time zone the rules are read in.
     */
    val zone: String,
    /**
     * The hub's local time now (`YYYY-MM-DDTHH:MM`).
     */
    val localTime: String,
    /**
     * The hub's clock reads before its build date: nothing runs.
     */
    val clockUnset: Boolean,
)

/**
 * One row of a run: an action on a target.
 */
data class HubScheduleResult(
    /**
     * The device ("" for a scene refused as a whole).
     */
    val serial: String,
    /**
     * The action, by position and `t` (`0:preset.load`).
     */
    val action: String,
    /**
     * It went through.
     */
    val ok: Boolean,
    /**
     * The hub's code when not (`offline`, `limit_exceeded`, ...).
     */
    val code: String,
    /**
     * Why, for a person.
     */
    val msg: String,
)

/**
 * A schedule's run (`schedule.run_now`'s answer, `schedule.ran`).
 */
data class HubScheduleRun(
    /**
     * The rule's id.
     */
    val rule: String,
    /**
     * Its name.
     */
    val name: String,
    /**
     * When (ISO-8601 UTC).
     */
    val at: String,
    /**
     * The admin who ran it now; "" on its schedule.
     */
    val by: String,
    /**
     * Each action on each target, in the rule's order.
     */
    val results: List<HubScheduleResult>,
)

/**
 * A target's last delivery try.
 */
data class HubOutboundLast(
    /**
     * When (ISO-8601 UTC).
     */
    val at: String,
    /**
     * It was delivered.
     */
    val ok: Boolean,
    /**
     * The receiver's HTTP status, if it answered.
     */
    val status: Int?,
    /**
     * Why not, for a person.
     */
    val msg: String,
)

/**
 * A notification target (`outbound.get`, `outbound.set`).
 */
data class HubOutboundTarget(
    /**
     * 1 to 32 of `A-Z a-z 0-9 _ -`; "" for a new one (the hub names it).
     */
    val id: String,
    /**
     * At most 64 characters; "" for the id.
     */
    val name: String,
    /**
     * `webhook` (a JSON POST) or `push` (an ntfy-style text POST).
     */
    val kind: String,
    /**
     * `https://`, or `http://` with [`HubOutboundTarget::plaintext`].
     */
    val url: String,
    /**
     * Deliveries go out.
     */
    val enabled: Boolean,
    /**
     * Of `alarm.raised`, `alarm.cleared`, `restart`, `schedule.ran`,
     * `schedule.failed`; empty sends none.
     */
    val kinds: List<String>,
    /**
     * Read: `set` or `not set`. In [`DspiCore::hub_outbound_set`]: `new`
     * (the hub makes one, shown once), `set` or "" (keep), `not set`
     * (none). A secret is never typed.
     */
    val secret: String,
    /**
     * `http://` to a private address, unencrypted.
     */
    val plaintext: Boolean,
    /**
     * The CA or self-signed certificate(s) to trust instead of the public
     * CAs (PEM); "" for none.
     */
    val caPem: String,
    /**
     * The receiver's key pin (`sha256//<base64>`); "" for none.
     */
    val pinSha256: String,
    /**
     * Deliveries waiting. Read only.
     */
    val queued: Long,
    /**
     * Deliveries dropped. Read only.
     */
    val dropped: Long,
    /**
     * The last try. Read only.
     */
    val last: HubOutboundLast?,
    /**
     * Sent over TLS. Read only.
     */
    val encrypted: Boolean,
    /**
     * `webpki`, `ca` or `pin` (https only); "" otherwise. Read only.
     */
    val trust: String,
    /**
     * A notice for the Admin (a target kept from before TLS). Read only.
     */
    val notice: String,
)

/**
 * A secret the hub made for a target, shown once ([`HubOutboundSet`]).
 */
data class HubOutboundSecret(
    /**
     * The target's id.
     */
    val target: String,
    /**
     * The secret (64 hex characters): show it once, keep it nowhere else.
     */
    val secret: HubSecret,
)

/**
 * `outbound.set`'s answer.
 */
data class HubOutboundSet(
    /**
     * The targets now.
     */
    val targets: List<HubOutboundTarget>,
    /**
     * The secrets made by this call: in this answer only.
     */
    val secrets: List<HubOutboundSecret>,
)

/**
 * `outbound.test`'s answer.
 */
data class HubOutboundTest(
    /**
     * It was delivered.
     */
    val delivered: Boolean,
    /**
     * The receiver's HTTP status, if it answered.
     */
    val status: Int?,
    /**
     * Why not, for a person.
     */
    val msg: String,
)

/**
 * TLS to the broker (`mqtt.get`'s `tls`). PEMs and file paths "" for none.
 */
data class HubMqttTls(
    /**
     * `on` or `off` ("" is off).
     */
    val mode: String,
    /**
     * The CA or self-signed certificate(s) to trust (PEM).
     */
    val caPem: String,
    /**
     * The broker's key pin.
     */
    val pinSha256: String,
    /**
     * A client certificate (PEM).
     */
    val clientCertPem: String,
    /**
     * Its key. Read: `set` or `not set`; send `set` back to keep it, a PEM
     * to set it, "" or `not set` to clear it.
     */
    val clientKeyPem: String,
    /**
     * A client certificate's file on the hub's machine.
     */
    val clientCertFile: String,
    /**
     * Its key's file (0600) on the hub's machine.
     */
    val clientKeyFile: String,
    /**
     * Without TLS, send the password to a broker not on loopback too.
     */
    val allowPlaintextPassword: Boolean,
)

/**
 * The broker setting (`mqtt.get`, `mqtt.set`). In
 * [`DspiCore::hub_mqtt_set`] "" in `client_id`, `base_topic` (and a `None`
 * `port`) is the hub's default, "" in `broker`/`username` none.
 */
data class HubMqttSettings(
    /**
     * The hub connects and publishes.
     */
    val enabled: Boolean,
    /**
     * The broker's host name or address.
     */
    val broker: String,
    /**
     * Its port (read: the one in use).
     */
    val port: Int?,
    /**
     * The client id (read: the one in use).
     */
    val clientId: String,
    /**
     * The user name; "" for none.
     */
    val username: String,
    /**
     * Read: `set` or `not set`. To set: the password itself (typed by the
     * Admin); `set` or "" keeps it; `not set` clears it. Never logged.
     */
    val password: String,
    /**
     * The base topic (read: the one in use).
     */
    val baseTopic: String,
    /**
     * TLS.
     */
    val tls: HubMqttTls,
    /**
     * Home Assistant discovery and `set` topics on (section 13.2).
     */
    val haEnabled: Boolean,
    /**
     * The API key (its `cid`) Home Assistant's `set` topics act as.
     */
    val haKey: Long?,
    /**
     * A one-time notice of this run (a file migrated). Read only.
     */
    val notice: String,
)

/**
 * The broker connection now (`mqtt.status`).
 */
data class HubMqttStatus(
    /**
     * `off`, `connecting`, `connected` or `failed`.
     */
    val state: String,
    /**
     * The last reason, for a person (a refused password).
     */
    val msg: String,
    /**
     * When `state` last changed (ISO-8601 UTC).
     */
    val since: String,
    /**
     * Publishes waiting while the broker is away.
     */
    val queued: Long,
    /**
     * Publishes dropped past that.
     */
    val dropped: Long,
    /**
     * The connection is TLS.
     */
    val encrypted: Boolean,
    /**
     * A one-time notice of this run.
     */
    val notice: String,
)

/**
 * An API key of the hub (`auth.list`'s rows of kind `api`).
 */
data class HubApiKey(
    /**
     * Its client id: what [`DspiCore::hub_api_key_revoke`] takes.
     */
    val cid: Long,
    /**
     * Its name.
     */
    val name: String,
    /**
     * `viewer`, `control` or `admin`.
     */
    val role: String,
    /**
     * Kept for when the port speaks TLS; no effect yet.
     */
    val plaintextOk: Boolean,
    /**
     * Its REST session is open.
     */
    val online: Boolean,
    /**
     * When it was minted (ISO-8601 UTC).
     */
    val created: String,
    /**
     * When it was last used; "" for never.
     */
    val lastSeen: String,
)

/**
 * A key the hub just minted (`auth.mint`): [`HubApiKeyMinted::key`] is
 * shown in this answer only.
 */
data class HubApiKeyMinted(
    /**
     * Its client id.
     */
    val cid: Long,
    /**
     * Its name, as the hub cleaned it.
     */
    val name: String,
    /**
     * Its role.
     */
    val role: String,
    /**
     * As asked.
     */
    val plaintextOk: Boolean,
    /**
     * The key (43 characters): show it once; the hub keeps only its hash.
     */
    val key: HubSecret,
)

/**
 * What [`DspiCore::hub_inventory_forget`] removed.
 */
data class HubInventoryForgot(
    /**
     * The device.
     */
    val serial: String,
    /**
     * What went, in order: `record`, then `events` if it had history files,
     * then `snapshots` if asked and it had any.
     */
    val forgot: List<String>,
)

/**
 * One change in the history ([`DspiCore::history`]).
 */
data class HistoryEntry(
    /**
     * The registry path (`out.gain`, `eq.freq`, ...), or one of the
     * journal's own: `eq.band` (a whole band: type, bypass, then freq, Q,
     * gain and the Linkwitz target Q as little-endian `f32`s), `ext.pairmap`
     * (the crossfeed pair map's four bytes), `ext.vreg` (a core-voltage
     * request: op and value), `raw` (a raw request: opcode and `wValue` as
     * indices, the payload as the value), `ext.alink.slots` (the 8
     * slot bytes), `ext.alink.phase` (mode, then the delay and the
     * hops offset as little-endian 16-bit values), `ext.alink.apply`
     * (op and arg as indices, the 16-byte request as the value) and
     * `ext.alink.stats_reset`. A control-surface operation is
     * under its `cs.*` path with the operation's JSON as text.
     */
    val path: String,
    /**
     * The path's indices (an output, a channel and a band, ...).
     */
    val indices: List<Int>,
    /**
     * The value before, when known; undo writes it back.
     */
    val before: ParamValue?,
    /**
     * The value after (`trigger` for an action).
     */
    val after: ParamValue,
    /**
     * Who made it.
     */
    val source: HistorySource,
    /**
     * When, in milliseconds since the Unix epoch (a drag: its last step).
     */
    val atMs: Long,
    /**
     * Whether undo may reverse it. The registry decides: only a parameter
     * with no hazard (not a flash write, an audible one, a reconfiguration,
     * a deferred or an irreversible one).
     */
    val undoable: Boolean,
    /**
     * The undo group's label ([`DspiCore::begin_group`]) when the change
     * was written inside one; `None` otherwise.
     */
    val label: String?,
)

/**
 * What [`DspiCore::undo`] or [`DspiCore::redo`] did.
 */
data class HistoryMove(
    /**
     * The change reversed (undo) or applied again (redo); `None` when
     * nothing moved.
     */
    val entry: HistoryEntry?,
    /**
     * The changes stepped over on the way, newest first, which cannot be
     * undone (see [`HistoryEntry::undoable`]). An entry here that is
     * undoable had no value before to restore, or someone else has changed
     * it since (`note` says who); the walk stopped there. A drag's step of
     * several values lists here each value someone else changed since, one
     * entry each, also when its other values moved.
     */
    val skipped: List<HistoryEntry>,
    /**
     * Why a value was left alone, in words, when another writer changed it
     * since (only where the core leaves such a change alone): nothing moved,
     * or, for a drag's step of several values, the others did. After an
     * undo of "Protect all outputs" it also says the limiters stay on
     * ([`PROTECT_UNDONE_NOTE`], WP P1EFIX). `None` otherwise.
     */
    val note: String?,
)

/**
 * The open device's limits ([`DspiCore::limits_status`]).
 */
data class LimitsStatus(
    /**
     * A profile is in force for the open device.
     */
    val active: Boolean,
    /**
     * The open device's serial ("" with none).
     */
    val serial: String,
    /**
     * How the profile was found: `none`, `ok`, `fell_back` (the profile
     * file is missing or unreadable; the last good copy is in force) or
     * `unreadable` (no good copy: running unlimited).
     */
    val state: String,
    /**
     * The standing notice's key (`limits.fell_back`, `limits.unreadable`;
     * `crate::notice_text`), "" when there is none to show.
     */
    val noticeKey: String,
    /**
     * Why, for the notice's detail line.
     */
    val detail: String,
    /**
     * What the last clamp held (an import, a recall, a profile applied, a
     * slot load), one row each, in the import's words.
     */
    val lastHeld: List<String>,
)

/**
 * What applying a profile did ([`DspiCore::limits_apply_profile`]).
 */
data class LimitsApply(
    /**
     * The report: "Held to the limits profile: ..." when the device was
     * outside a narrowed limit, nothing otherwise.
     */
    val lines: List<String>,
    /**
     * What moved, one row each.
     */
    val held: List<String>,
    /**
     * Writes that failed, and why (the profile is kept all the same).
     */
    val notes: List<String>,
)

/**
 * One limits field's range, for a client's limits editor
 * ([`limits_field_ranges`]).
 */
data class LimitFieldRange(
    /**
     * The profile document's field: `maxGainDb`, `limiterCeilingDb`,
     * `highpassMinHz`, `highpassMinSlopeDb`, `delayMinMs`, `delayMaxMs`
     * (each output's), `maxPeqBoostDb`, `masterVolumeMaxDb` (the device's).
     */
    val key: String,
    /**
     * A field of each output's limits.
     */
    val perOutput: Boolean,
    /**
     * `dB`, `dBFS`, `Hz`, `dB/oct` or `ms`.
     */
    val unit: String,
    /**
     * The lowest value the profile keeps.
     */
    val min: Float,
    /**
     * The highest value the profile keeps.
     */
    val max: Float,
    /**
     * The editor's step.
     */
    val step: Float,
)

/**
 * The open device's installer lock on this console
 * ([`DspiCore::installer_lock_state`]).
 */
data class LockState(
    /**
     * The open device's serial ("" with none).
     */
    val serial: String,
    /**
     * An installer PIN is set for it on this console (an unreadable PIN
     * file counts as set; `detail` says why).
     */
    val pinSet: Boolean,
    /**
     * A PIN is set and this console is unlocked for the device, this
     * session.
     */
    val unlocked: Boolean,
    /**
     * The locked-user state: a PIN is set, the lock covers something and
     * this console is not unlocked. Only `allowed_writes` pass.
     */
    val locked: Boolean,
    /**
     * The Installer pages, the profile and the PIN may change without a
     * PIN prompt: no PIN is set, or the console is unlocked.
     */
    val installerOpen: Boolean,
    /**
     * What the lock covers: the mode manifest's screen ids (the profile's
     * `lockedPages`); empty: a PIN alone locks nothing.
     */
    val covers: List<String>,
    /**
     * The writes the locked-user state allows (registry paths).
     */
    val allowedWrites: List<String>,
    /**
     * Wrong PINs since the last good one.
     */
    val wrongTries: Long,
    /**
     * How long until the next attempt is allowed, ms; 0: now.
     */
    val retryAfterMs: Long,
    /**
     * Unlocked with the recovery code: the installer should set a new PIN.
     */
    val recovered: Boolean,
    /**
     * The installer's note, for the locked front page.
     */
    val note: String,
    /**
     * How to reach the installer.
     */
    val contact: String,
    /**
     * The notice the unlock dialog shows in one line: the lock is on this
     * console, the DSPi itself is open (`installer_lock.scope`); or, when
     * the hub holds it, the hub's PIN unlocks it (`installer_lock.hub`).
     */
    val scopeNoticeKey: String,
    /**
     * Why the PIN's file is unreadable, when it is.
     */
    val detail: String,
    /**
     * Which lock this is: `console` (this console's PIN), `hub` (the DSPi
     * Link hub the device is reached through holds the PIN; unlocking asks
     * the hub), or "" with no PIN. One lock, one prompt.
     */
    val heldBy: String,
    /**
     * The mode the hub pins for this console's role on this device
     * (`mode.pinned`), "" for none.
     */
    val hubPinnedMode: String,
)

/**
 * A PIN just set ([`DspiCore::installer_pin_set`]).
 */
data class InstallerPin(
    /**
     * The recovery code (`XXXXX-XXXXX-XXXXX-XXXXX`): shown this once, for
     * the hand-over note, never kept but as a hash (notice
     * `installer_lock.recovery`).
     */
    val recoveryCode: String,
    /**
     * The lock now.
     */
    val state: LockState,
)

/**
 * What to tell the user about a [`LinkPhase`].
 */
data class LinkPhaseText(
    /**
     * Stable key of `text`, for localising: `no_device`, `needs_pairing.fixed`.
     */
    val key: String,
    /**
     * The phase's name ([`link_phase_key`]), also for an entry split by
     * `pin_source`.
     */
    val phase: String,
    /**
     * The English.
     */
    val text: String,
    /**
     * Stable key of `action`, if the phase has a button of its own.
     */
    val actionKey: String?,
    /**
     * The English of that button.
     * [`LinkPhase::Reconnecting`] has one, which calls `link_close`: the owner's
     * rule is that a lost connection always offers the way out.
     */
    val action: String?,
)

/**
 * A mode: Simple, Advanced or Installer.
 */
data class ModeEntry(
    /**
     * `simple`, `advanced` or `installer`.
     */
    val id: String,
    /**
     * The mode's name in the UI.
     */
    val label: String,
    /**
     * The platform classes that open in this mode by default.
     */
    val defaultOn: List<String>,
    /**
     * Behind the installer's PIN when one is set (and only then).
     */
    val needsPinWhenSet: Boolean,
)

/**
 * What the locked-user state shows and allows.
 */
data class ModesLockedUser(
    /**
     * The state's name in the UI (a badge).
     */
    val label: String,
    /**
     * Its screens, in order.
     */
    val screens: List<String>,
    /**
     * What its Settings shows (`about`, `installer_note`).
     */
    val settings: List<String>,
    /**
     * The writes it allows, by registry path (the core enforces them).
     */
    val writes: List<String>,
)

/**
 * A screen and the modes that show it.
 */
data class ModeScreen(
    /**
     * Stable id (`front`, `system`, ...; a lock's cover names these).
     */
    val id: String,
    /**
     * The title in the UI.
     */
    val title: String,
    /**
     * The modes (and `locked_user`) that show it.
     */
    val modes: List<String>,
    /**
     * The modes it is the first screen of.
     */
    val firstIn: List<String>,
    /**
     * `pro` for a Pro-layer screen a client shows once it has built it
     * (else the next screen of the list stands in); "" otherwise.
     */
    val layer: String,
    /**
     * The platform classes it is for; empty: all.
     */
    val platforms: List<String>,
)

/**
 * An operation and the modes that offer it.
 */
data class ModeOperation(
    /**
     * Stable id (`firmware`, `factory_reset`, ...).
     */
    val id: String,
    /**
     * The title in the UI.
     */
    val title: String,
    /**
     * The modes that offer it.
     */
    val modes: List<String>,
    /**
     * The platform classes it is for; empty: all.
     */
    val platforms: List<String>,
    /**
     * Behind its usual confirmation.
     */
    val confirm: Boolean,
)

/**
 * The mode manifest (`assets/modes/modes.json`).
 */
data class ModeManifest(
    /**
     * The format, 1.
     */
    val version: Long,
    /**
     * The platform classes: `phone`, `desktop`, `web`.
     */
    val platforms: List<String>,
    /**
     * The modes, in the order a switch lists them.
     */
    val modes: List<ModeEntry>,
    /**
     * The locked-user state.
     */
    val lockedUser: ModesLockedUser,
    /**
     * The screens, in order.
     */
    val screens: List<ModeScreen>,
    /**
     * The operations that depend on the mode.
     */
    val operations: List<ModeOperation>,
)

/**
 * The mode a client shows, and why ([`DspiCore::mode_resolve`]).
 */
data class ModeChoice(
    /**
     * The mode to show: `simple`, `advanced`, `installer` or `locked_user`.
     */
    val mode: String,
    /**
     * Why: `locked` (the locked-user state), `pinned` (the hub's),
     * `chosen` (the user's) or `default` (the platform class's).
     */
    val reason: String,
    /**
     * The user may switch modes (no lock, no pinned mode).
     */
    val switchable: Boolean,
    /**
     * The mode asked for (chosen or pinned) is the Installer, an installer
     * PIN is set and the console is not unlocked: ask for the PIN
     * (`installer_unlock`); `mode` is the default meanwhile. Never with no
     * PIN set.
     */
    val needsPin: Boolean,
    /**
     * The modes the switch offers with no PIN prompt.
     */
    val openModes: List<String>,
    /**
     * The screens of `mode` for this platform class, in order.
     */
    val screens: List<String>,
    /**
     * The first of them.
     */
    val firstScreen: String,
    /**
     * The operations `mode` offers on this platform class.
     */
    val operations: List<String>,
)

/**
 * One filter type and the name clients show for it.
 */
data class FilterTypeName(
    /**
     * The firmware's type code (`FILTER_*`): 0..13 PEQ, 32..63 crossover.
     */
    val code: Int,
    /**
     * The name, e.g. "High Cut (12dB)".
     */
    val name: String,
)

/**
 * What to tell the user about an error.
 */
data class Notice(
    /**
     * Stable key, for localising: `disconnected`, `dlink.wrong_pin`.
     */
    val key: String,
    /**
     * How to show it.
     */
    val kind: NoticeKind,
    /**
     * A short title.
     */
    val title: String,
    /**
     * Why it happened.
     */
    val reason: String,
    /**
     * What to do.
     */
    val action: String,
    /**
     * The error's own words (may be empty); not localised.
     */
    val detail: String,
)

/**
 * One output's label.
 */
data class OutputLabel(
    /**
     * 0-based output index.
     */
    val output: Int,
    /**
     * What to show: the user's name, else "Out 1 · R · Low".
     */
    val label: String,
    /**
     * The same for a phone row, beside the output's "OUTn" button: the
     * user's name, else "R · Low" (owner decision, review c86 F3).
     */
    val shortLabel: String,
    /**
     * The firmware's name for the slot ("I2S 1 L", "PDM"), for a tooltip or
     * a detail line.
     */
    val slotName: String,
    /**
     * The output has a name the user set; `label` is that name.
     */
    val userNamed: Boolean,
    /**
     * "L", "R", "L+R", an input's name, "Mix", or "None".
     */
    val channel: String,
    /**
     * "Low", "High", "Band" or "Full".
     */
    val band: String,
)

/**
 * One dashboard card: two outputs side by side, or one alone.
 */
data class OutputCard(
    /**
     * 0-based output index of the left (or only) column.
     */
    val left: Int,
    /**
     * The right column's output; none for a card of one output.
     */
    val right: Int?,
    /**
     * "Woofers", "Tweeters" or "Mids" for a pair on one band with default
     * names whose left output plays L and right output R by the routing;
     * empty otherwise.
     */
    val title: String,
    /**
     * The columns' headings: "Woofers L" / "Woofers R" under a title, else
     * the outputs' labels.
     */
    val leftName: String,
    /**
     * The right column's heading; empty for a card of one output.
     */
    val rightName: String,
    /**
     * The left column's heading on a phone: "Woofers L" under a title, else
     * the output's short label ("R · Low").
     */
    val leftShortName: String,
    /**
     * The right column's heading on a phone: "R" under a title, else the
     * output's short label; empty for a card of one output.
     */
    val rightShortName: String,
)

/**
 * The state the labels read, for a client that keeps its own copy.
 */
data class OutputLabelInput(
    /**
     * Live input channels.
     */
    val numInputs: Int,
    /**
     * Live output channels, the PDM sub last.
     */
    val numOutputs: Int,
    /**
     * Per slot: 1 = I2S, else S/PDIF.
     */
    val outputTypes: List<Int>,
    /**
     * Channel names in wire order: inputs, then outputs.
     */
    val channelNames: List<String>,
    /**
     * Crosspoint on, `[input][output]`.
     */
    val matrixRouting: List<List<Boolean>>,
    /**
     * Each output's bands: PEQ and crossover, in any order.
     */
    val outputFilters: List<List<FilterParams>>,
    /**
     * Output enabled, per output.
     */
    val outputEnabled: List<Boolean>,
    /**
     * The K340 crossfeed pair map, 4 bytes; empty or zero elsewhere.
     */
    val crossfeedPairMap: List<Int>,
)

/**
 * A board in BOOTSEL mode with a PICOBOOT interface.
 */
data class BootDevice(
    /**
     * 0 RP2040 (`2E8A:0003`), 1 RP2350 (`2E8A:000F`), as `Uf2Info::platform`.
     */
    val platform: Int,
    /**
     * The boot ROM's USB serial. On an RP2350 it is the chip's unique id,
     * which is the DSPi's serial; the RP2040's ROM reports a fixed string,
     * so it is `None` there and only uniqueness identifies the board.
     */
    val serial: String?,
    /**
     * Where it is on the bus (`<bus>-<port>.<port>...`), stable across a
     * re-enumeration on the same port.
     */
    val busLocation: String,
)

/**
 * What a PICOBOOT flash did.
 */
data class FlashReport(
    /**
     * The target's platform.
     */
    val platform: Int,
    /**
     * The target's serial, as [`BootDevice::serial`].
     */
    val serial: String?,
    /**
     * The image's DSPi version (`Uf2Info::firmware_version`), "" if none.
     */
    val firmwareVersion: String,
    /**
     * 4 KiB sectors erased, written and read back.
     */
    val sectors: Long,
    /**
     * Bytes written (whole sectors).
     */
    val bytesWritten: Long,
    /**
     * How long it took, in ms.
     */
    val elapsedMs: Long,
)

/**
 * One function: its kind and, for the indexed kinds, which one.
 */
data class PinFunction(
    /**
     * What it is.
     */
    val kind: PinFunctionKind,
    /**
     * Which one (output, input, pair or slot); 0 for the single ones.
     */
    val index: Int,
)

/**
 * One GPIO and the function holding it.
 */
data class PinHolder(
    /**
     * The GPIO.
     */
    val pin: Int,
    /**
     * The function holding it (BCK's also holds LRCLK, BCK + 1).
     */
    val function: PinFunction,
    /**
     * For grouping.
     */
    val role: PinHolderRole,
    /**
     * The Console's owner name, e.g. "Output 1", "I2S LRCLK", "UART
     * Control" (English; `function` is there to translate from).
     */
    val label: String,
)

/**
 * One function of this device: its pin, whether it holds it, and the pins
 * it may move to.
 */
data class PinFunctionInfo(
    /**
     * Which function.
     */
    val function: PinFunction,
    /**
     * Its name, e.g. "Output 1", "S/PDIF 2 RX", "UART TX".
     */
    val label: String,
    /**
     * Its GPIO, [`PIN_NONE`] when it has none.
     */
    val pin: Int,
    /**
     * Whether it holds that pin now (a disabled feature holds nothing).
     */
    val holds: Boolean,
    /**
     * The GPIOs [`pin_check`] accepts for it, its own included, in order.
     * For a disabled optional S/PDIF input, without the pins another
     * function holds: it could store one, but never be enabled on it.
     * Empty where nothing is assignable.
     */
    val choices: List<Int>,
    /**
     * Output slots: whether the slot may be switched to I2S (the STM32H723's
     * SAI rule; always on an RP2040/RP2350). False for everything else.
     */
    val i2sAllowed: Boolean,
)

/**
 * The whole map.
 */
data class PinMap(
    /**
     * The platform the rules are for (`DspState.platform_id`).
     */
    val platformId: Int,
    /**
     * Whether this platform has assignable pins (RP2040 and RP2350).
     */
    val assignable: Boolean,
    /**
     * The platform's valid GPIOs, in order; empty where nothing is
     * assignable.
     */
    val validPins: List<Int>,
    /**
     * The functions this device has, in the Console's order.
     */
    val functions: List<PinFunctionInfo>,
    /**
     * Who holds each held GPIO, in pin order; the first claim wins where
     * two share one (the ADAT loopback shows as "ADAT Output").
     */
    val holders: List<PinHolder>,
)

/**
 * A refused pin.
 */
data class PinRefusal(
    /**
     * Why.
     */
    val reason: PinRefusalReason,
    /**
     * The `PIN_CONFIG_*` status the firmware answers for it (1 invalid
     * pin, 2 in use, 3 no such output, 4 output active).
     */
    val status: Int,
    /**
     * For [`PinRefusalReason::InUse`], the function holding the pin.
     */
    val holder: PinHolder?,
)

/**
 * One notification as the tap saw it (WP CG23).
 */
data class RawNotification(
    /**
     * The packet in the firmware's v2 layout (`notify.h`), or the 8-byte v1
     * volume packet. Rebuilt from the decoded event, with the flags and the
     * padding zero as the firmware sends them: byte for byte what the
     * device sent for every event this build knows. A packet the reader
     * could not decode is kept as it came.
     */
    val packet: List<Int>,
    /**
     * The link's attribution: the DSPi Link session id of the writer, 0
     * for the device itself; `None` over USB and MIDI.
     */
    val origin: Int?,
    /**
     * The echo filter's verdict: the echo of a write of this core's own.
     * Only a `PARAM_CHANGED` or a `BULK_INVALIDATED` can be one; every
     * other event is `false`.
     */
    val own: Boolean,
    /**
     * Something before this entry is missing: the tap's ring overflowed,
     * or the reader saw a gap in the device's sequence numbers.
     */
    val lost: Boolean,
    /**
     * When the reader received it, ms since the Unix epoch.
     */
    val receivedMs: Long,
)

/**
 * One snapshot in a list ([`DspiCore::snapshot_list`]).
 */
data class SnapshotInfo(
    /**
     * The store's id, for the other calls.
     */
    val id: String,
    /**
     * The user's name; any Unicode.
     */
    val name: String,
    /**
     * The user's note; any Unicode.
     */
    val note: String,
    /**
     * The serial of the device it was taken from.
     */
    val serial: String,
    /**
     * When it was taken, ms since the Unix epoch.
     */
    val savedMs: Long,
    /**
     * The platform it was taken on (`RP2040`, `RP2350`), "" when unknown.
     */
    val platform: String,
    /**
     * The device's input channels then, 0 when unknown.
     */
    val inputChannels: Int,
    /**
     * The device's output channels then, 0 when unknown.
     */
    val outputChannels: Int,
    /**
     * The wire format of its image, 0 when unknown.
     */
    val wireFormat: Int,
)

/**
 * What a recall did ([`DspiCore::snapshot_recall`]).
 */
data class SnapshotRecall(
    /**
     * The snapshot's name.
     */
    val name: String,
    /**
     * Whether the snapshot's own image was written (false: a document
     * without one, written through the import's path).
     */
    val image: Boolean,
    /**
     * What changed, in the unsaved-changes list's words, then the settings
     * outside the image that were rewritten.
     */
    val changes: List<String>,
    /**
     * What was not written, and why (a feature this firmware lacks, a part
     * the device refused, a value held to the device's range).
     */
    val notes: List<String>,
)

/**
 * A voltage the flow offers on the connected device.
 */
data class VregChoice(
    /**
     * VREG code.
     */
    val code: Int,
    /**
     * The voltage, mV.
     */
    val millivolts: Int,
    /**
     * A trial of it would raise this unit above 1.20 V now, so `OVERVOLT`
     * must be typed.
     */
    val needsWord: Boolean,
    /**
     * The same for a save (`core_vreg_manual_set`), which does not count a
     * running trial as current.
     */
    val saveNeedsWord: Boolean,
)

/**
 * The flow as a client shows it.
 */
data class VregCalView(
    /**
     * The connection can use the flow: `EXT_CORE_VREG` present, writable,
     * and not refused by a hub. While false with phase `Idle`, hide the
     * flow. While false in another phase the device is away: show the phase.
     */
    val available: Boolean,
    /**
     * Where the flow is.
     */
    val phase: VregCalPhase,
    /**
     * A stable key for `message`, for clients that localise.
     */
    val messageKey: String,
    /**
     * The state or result, stated plainly in English.
     */
    val message: String,
    /**
     * The warning to show before the flow, with the datasheet limits.
     */
    val warning: String,
    /**
     * What a soak does and does not show.
     */
    val soakNote: String,
    /**
     * The voltages offered, lowest first. Empty on a build default the flow
     * does not cover, or before a first status.
     */
    val choices: List<VregChoice>,
    /**
     * What to type when `needs_word` or `commit_needs_word`: `OVERVOLT`,
     * exactly.
     */
    val confirmationWord: String,
    /**
     * `core_vreg_cal_commit` needs the word now, while `phase` is `Passed`.
     * Saving a trial above 1.20 V that is not already stored asks for it, even
     * though it was typed to start the trial: going from RAM to flash is an
     * upward change of its own. Ask again; do not reuse the earlier answer.
     */
    val commitNeedsWord: Boolean,
    /**
     * `core_vreg_manual_set(0, ..)`, the reset to the build default, needs the
     * word now: the unit's current voltage cannot be read from the last
     * status, so nobody can say the reset does not raise it (WP QD28b).
     */
    val resetNeedsWord: Boolean,
    /**
     * The soak to suggest, seconds.
     */
    val defaultSoakS: Long,
    /**
     * The shortest soak accepted, seconds.
     */
    val minSoakS: Long,
    /**
     * The run's or found trial's voltage; 0 if none.
     */
    val targetVreg: Int,
    /**
     * The soak asked for, seconds; 0 if none.
     */
    val soakS: Long,
    /**
     * Seconds of soak counted so far.
     */
    val elapsedS: Long,
    /**
     * The failure shown or on record: its voltage; 0 if none.
     */
    val failedVreg: Int,
    /**
     * Seconds the failed trial ran, if this host saw it start and the record
     * still has the time.
     */
    val ranS: Long?,
    /**
     * The device's uptime when that trial hung; 0 if the record lost it. Its
     * whole run, so at most an upper bound on the trial.
     */
    val uptimeAtHangS: Long,
    /**
     * The next voltage up to offer after that failure; 0 if none.
     */
    val nextVreg: Int,
    /**
     * Nothing above that failure to try: a hardware problem.
     */
    val hardwareProblem: Boolean,
    /**
     * Why the result is unknown (`record_gone`, `not_started`,
     * `trial_changed`); `None` unless `phase` is `Unknown`.
     */
    val unknownReason: String?,
    /**
     * The device stopped answering since the last status: a hang in
     * progress, or a dropped link. The result is still open.
     */
    val linkLost: Boolean,
    /**
     * `core_vreg_cal_start` applies now.
     */
    val canStart: Boolean,
    /**
     * `core_vreg_cal_keep` applies now.
     */
    val canKeep: Boolean,
    /**
     * `core_vreg_cal_commit` applies now.
     */
    val canCommit: Boolean,
    /**
     * The last status read from the device.
     */
    val status: CoreVregInfo?,
    /**
     * Why the last call or read failed, in a sentence; `None` once one
     * succeeded.
     */
    val lastError: String?,
)

/**
 * Where a Link session is in its life, for the status line.
 */
enum class LinkPhase {
    /**
     * No session.
     */
    IDLE,
    /**
     * The hub wants a PIN.
     */
    NEEDS_PAIRING,
    /**
     * The hub has no device.
     */
    NO_DEVICE,
    /**
     * The hub has several devices: pick one.
     */
    CHOOSE_DEVICE,
    /**
     * Bound to a device.
     */
    BOUND,
    /**
     * Waiting to reconnect.
     */
    RECONNECTING,
    /**
     * Closed by the hub or the client.
     */
    CLOSED,
    /**
     * Refused by the hub.
     */
    REFUSED,
}

/**
 * How healthy an output fill is.
 */
enum class FillBand {
    /**
     * Comfortable.
     */
    GOOD,
    /**
     * Getting close to an edge.
     */
    WARN,
    /**
     * At or past an edge.
     */
    BAD,
}

/**
 * One side of a compare.
 */
enum class AbSide {
    /**
     * The first snapshot (the captured state when none was given).
     */
    A,
    /**
     * The second snapshot.
     */
    B,
}

/**
 * An operation that takes a confirmation token.
 */
enum class ConfirmOp {
    /**
     * Save the live state to a preset slot ([`DspiCore::save_preset_confirmed`]).
     */
    SAVE_PRESET,
    /**
     * Copy a preset ([`DspiCore::copy_preset_confirmed`]).
     */
    COPY_PRESET,
    /**
     * Delete a preset ([`DspiCore::delete_preset_confirmed`]).
     */
    DELETE_PRESET,
    /**
     * Save the live state to the active slot ([`DspiCore::save_params_confirmed`]).
     */
    SAVE_PARAMS,
    /**
     * Factory reset ([`DspiCore::factory_reset_confirmed`]).
     */
    FACTORY_RESET,
    /**
     * Save the output configuration ([`DspiCore::save_output_config_confirmed`]).
     */
    SAVE_OUTPUT_CONFIG,
    /**
     * Restart into the bootloader ([`DspiCore::enter_bootloader_confirmed`]).
     */
    ENTER_BOOTLOADER,
    /**
     * Import a configuration document ([`DspiCore::config_import_confirmed`]).
     */
    CONFIG_IMPORT,
    /**
     * Store a core voltage ([`DspiCore::core_vreg_cal_commit_confirmed`],
     * [`DspiCore::core_vreg_manual_set_confirmed`]).
     */
    VREG_SAVE,
    /**
     * Write a firmware image to the bootloader drive
     * ([`DspiCore::flash_confirmed`]).
     */
    FIRMWARE_FLASH,
}

/**
 * Where a [`FirmwareGuardBoard`]'s voltage came from.
 */
enum class FirmwareGuardBoardSource {
    /**
     * No device was open.
     */
    NO_DEVICE,
    /**
     * The board is in the bootloader, where it cannot be asked.
     */
    BOOTLOADER,
    /**
     * The device was open, but gave no answer that can be believed.
     */
    READ_FAILED,
    /**
     * `EXT_CORE_VREG`.
     */
    EXT_CORE_VREG,
    /**
     * The status block's live voltage, on firmware without `core_vreg`.
     */
    STATUS_BLOCK,
}

/**
 * The guard's answer. Flash only on [`FirmwareGuardVerdict::allowed`].
 */
enum class FirmwareGuardDecision {
    /**
     * The image is not firmware. Confirmation does not help.
     */
    REFUSED,
    /**
     * Blocked until the phrase is typed.
     */
    NEEDS_CONFIRMATION,
    /**
     * There was a risk, and the phrase was typed.
     */
    CONFIRMED,
    /**
     * No known risk.
     */
    CLEAR,
}

/**
 * Why, as a stable key for clients that localise the message.
 */
enum class FirmwareGuardReason {
    /**
     * The image failed the UF2 check.
     */
    IMAGE_INVALID,
    /**
     * No known risk.
     */
    NO_RISK,
    /**
     * At-risk board; the image does not say what voltage it runs at.
     */
    IMAGE_UNKNOWN,
    /**
     * At-risk board; the image is stamped below what the board needs.
     */
    IMAGE_LOWER,
    /**
     * The board's needs are not known.
     */
    BOARD_UNKNOWN,
    /**
     * WP CG14: the image runs above 1.20 V and above the board's current
     * voltage. Its `confirmation_phrase` is the word `OVERVOLT`.
     */
    OVERVOLT,
}

/**
 * [`verify_bundled`]'s answer: is this the firmware image the app bundles?
 */
enum class BundledFirmware {
    /**
     * A bundled name, and the bytes are the ones the manifest lists.
     */
    VERIFIED,
    /**
     * Not a bundled name: label it "not a verified DSPi Console image" and
     * keep the usual confirmations. Not a refusal.
     */
    NOT_BUNDLED,
    /**
     * A bundled name (or, before a flash, a bundled image's identity) with
     * other bytes: a mixed-up or damaged copy. Flashing it is refused.
     */
    MISMATCH,
}

/**
 * Where a guarded apply stands ([`GuardedApply::phase`]).
 */
enum class GuardPhase {
    /**
     * None has been begun on this core.
     */
    IDLE,
    /**
     * Applied; waiting for Keep or Revert. The countdown runs.
     */
    WAITING,
    /**
     * Kept: by Keep, or because another console took the device over.
     */
    KEPT,
    /**
     * The settings from before are back.
     */
    REVERTED,
    /**
     * Putting them back failed; it is not tried again.
     */
    REVERT_FAILED,
    /**
     * The hub went to put them back and the device was not there: nothing
     * was written.
     */
    NOT_WRITTEN,
    /**
     * The connection was lost. With the hub's guard this lasts until the
     * hub says how it ended; without it, the device may still hold the
     * change, and Revert works once the same device is open again.
     */
    LOST,
}

/**
 * Who made a change in the history.
 */
enum class HistorySource {
    /**
     * A write this program asked for.
     */
    LOCAL,
    /**
     * The reversal of an earlier change, sent by [`DspiCore::undo`].
     */
    UNDO,
    /**
     * The repeat of an undone change, sent by [`DspiCore::redo`].
     */
    REDO,
}

/**
 * How a notice is shown.
 */
enum class NoticeKind {
    /**
     * Nothing went wrong; something to know.
     */
    INFO,
    /**
     * Not done, for a reason the user can change or wait out.
     */
    WARNING,
    /**
     * Not done: something failed.
     */
    ERROR,
}

/**
 * A function that can hold a GPIO. The C ABI passes it as its code (the
 * number in brackets).
 */
enum class PinFunctionKind {
    /**
     * (0) A physical output, `index` 0..`num_pin_outputs`: the S/PDIF or
     * I2S slots, then the PDM subwoofer last.
     */
    OUTPUT,
    /**
     * (1) The I2S bit clock of the master (or unified) pair; also holds
     * LRCLK, BCK + 1.
     */
    I2S_BCK,
    /**
     * (2) The slave pair's bit clock (split clock-pin mode); also its LRCLK.
     */
    I2S_BCK_SLAVE,
    /**
     * (3) The I2S master clock.
     */
    MCK,
    /**
     * (4) An S/PDIF receiver, `index` 0..3.
     */
    SPDIF_RX,
    /**
     * (5) An I2S input data pin, `index` = stereo pair 0..3.
     */
    I2S_RX,
    /**
     * (6) The ADAT output (RP2350).
     */
    ADAT_OUT,
    /**
     * (7) The ADAT input (RP2350).
     */
    ADAT_IN,
    /**
     * (8) The DAC hardware mute line.
     */
    DAC_MUTE,
    /**
     * (9) The UART control interface's TX.
     */
    UART_TX,
    /**
     * (10) Its RX.
     */
    UART_RX,
    /**
     * (11) The I2C control interface's SDA.
     */
    I2C_SDA,
    /**
     * (12) Its SCL.
     */
    I2C_SCL,
    /**
     * (13) A control-surface binding, `index` = its slot.
     */
    CONTROL_SURFACE,
}

/**
 * What a held GPIO is doing, for grouping (the Console's five roles).
 */
enum class PinHolderRole {
    /**
     * A physical or ADAT output.
     */
    OUTPUT,
    /**
     * An I2S clock.
     */
    CLOCK,
    /**
     * An audio input.
     */
    INPUT,
    /**
     * A control interface or control surface.
     */
    CONTROL,
    /**
     * The DAC mute.
     */
    UTILITY,
}

/**
 * Why a pin was refused.
 */
enum class PinRefusalReason {
    /**
     * This platform's pins are fixed (STM32H723, or a platform this build
     * does not know).
     */
    NOT_ASSIGNABLE,
    /**
     * The device has no such function (an output, input or pair past its
     * count; ADAT on an RP2040; a feature its firmware lacks).
     */
    NO_SUCH_FUNCTION,
    /**
     * Not a GPIO this platform allows (23-25 are power and LED; BCK also
     * needs BCK + 1).
     */
    INVALID_PIN,
    /**
     * A GPIO, but not one this function's peripheral can use: MCK off a
     * clock-output pin, UART or I2C off its mux position or instance.
     */
    WRONG_MUX,
    /**
     * Another function holds it: see `holder`.
     */
    IN_USE,
    /**
     * The function cannot move now: MCK while enabled, the I2S clock pair
     * while I2S outputs run on it.
     */
    OUTPUT_ACTIVE,
    /**
     * The ADAT input's pin cannot be cleared while the input is enabled.
     */
    CLEAR_WHILE_ENABLED,
}

/**
 * Where a run is: [`VregCalView::phase`]. The details are in the view.
 */
enum class VregCalPhase {
    /**
     * The flow is not open.
     */
    IDLE,
    /**
     * Open: show the warning and what the device has on record.
     */
    REVIEW,
    /**
     * Clearing the device's record before the trial.
     */
    CLEARING,
    /**
     * The trial was sent and is not seen running yet.
     */
    STARTING_TRIAL,
    /**
     * The trial runs; the soak is counting. Abort is available.
     */
    SOAKING,
    /**
     * Passed: the trial still runs and nothing is saved. Commit or end.
     */
    PASSED,
    /**
     * The trial hung: `failed_vreg`, `ran_s`, `next_vreg`, `hardware_problem`.
     */
    FAILED,
    /**
     * The result cannot be known: run again.
     */
    UNKNOWN,
    /**
     * A trial nobody here started is running: end or keep.
     */
    TRIAL_FOUND,
    /**
     * A kept trial outside the flow's range: left alone, cannot pass.
     */
    TRIAL_LEFT_RUNNING,
    /**
     * Ending the trial.
     */
    ENDING,
    /**
     * The trial ended.
     */
    ENDED,
    /**
     * Saving: waiting to read the voltage back.
     */
    COMMITTING,
    /**
     * Saved and read back.
     */
    COMMITTED,
    /**
     * A save or an end did not show in time. Nothing was retried.
     */
    VERIFY_FAILED,
}

/**
 * What can happen to the demo device: [`DspiCore::core_vreg_demo_event`].
 */
enum class VregDemoEvent {
    /**
     * The watchdog fires.
     */
    HANG,
    /**
     * A requested reboot: no failure on record.
     */
    REBOOT,
    /**
     * Power lost: every record gone.
     */
    POWER_CYCLE,
    /**
     * `seconds` pass on the device's clock.
     */
    ADVANCE_UPTIME,
}

/**
 * A parameter value: `dspi_proto::value::Value` across the bindings. In
 * JSON (the C ABI, the web binding) it is tagged by kind in lower case:
 * `{"float": -12.5}`, `{"bool": true}`, `{"bytes": [1, 2]}`, `"trigger"`.
 */
sealed class ParamValue {
    /**
     * A yes/no value.
     */
    data class Bool(val v1: kotlin.Boolean) : ParamValue()
    /**
     * A number.
     */
    data class Float(val v1: kotlin.Float) : ParamValue()
    /**
     * A whole number.
     */
    data class Int(val v1: kotlin.Long) : ParamValue()
    /**
     * A choice, as its wire number (the registry has the labels).
     */
    data class Choice(val v1: kotlin.Int) : ParamValue()
    /**
     * A bit mask.
     */
    data class Mask(val v1: kotlin.Long) : ParamValue()
    /**
     * Text.
     */
    data class Text(val v1: kotlin.String) : ParamValue()
    /**
     * A structured payload, as the registry's packet encodes it.
     */
    data class Bytes(val v1: kotlin.collections.List<kotlin.Int>) : ParamValue()
    /**
     * An action with no value.
     */
    data object Trigger : ParamValue()
}

/**
 * A rebuild running on the core's threads. Poll it from a UI timer; dropping it
 * cancels it, without waiting for the requests in flight.
 */
interface AutoEqRebuild : AutoCloseable {
    /**
     * The newest progress. Does not block.
     */
    fun poll(): AutoEqRebuildProgress
    /**
     * Stop at the next batch of profiles; nothing is written. Does not block:
     * keep polling until `finished`.
     */
    fun cancel()
}

/**
 * A secret the hub made and shows once: an API key, a webhook's secret. An
 * object, not a string field, so that no binding's generated record
 * printing (Kotlin `toString`, Swift `description`) shows it: read it with
 * [`HubSecret::reveal`] to show it once, and keep it nowhere else. Its
 * `Debug` is `set`; serialized (the C and wasm answers) it is the plain
 * string.
 */
interface HubSecret : AutoCloseable {
    /**
     * The secret's text, to show once. No I/O.
     */
    fun reveal(): String
}
